!$WHITE = "#FFF"
!$GRAY_LIGHT = "#222"
!$GRAY = "#868e96"
!$PRIMARY = "#DF691A"
!$SECONDARY = "#4E5D6C"
!$SUCCESS = "#5cb85c"
!$INFO = "#5bc0de"
!$WARNING = "#f0ad4e"
